11	// TestHistoricalBillsKeepLockedTermsAcrossChangeCancelResubscribe 是历史账单
12	// 计价的端到端回归：同一账户先安排换套餐（锁定目标套餐当时的完整条件）、
13	// 按月取消、空档一个月后按修改过的套餐重新开通，再先出新月账单、后补开旧月
14	// 账单。旧账期必须使用那段订阅当时锁定的条件快照，既不能被后来的订阅覆盖，
15	// 也不能被同一套餐的新价格覆盖。
16	//
17	// 时间线（全部 UTC）：
18	//
19	//	2026-01-01 开通套餐甲：月费 1000、额度 10、超额单价 100、税率 10%。
20	//	2026-01-15 安排 2 月起换套餐乙，安排时乙：月费 2000、额度 20、
21	//	           超额单价 200、税率 10%；安排锁定该完整快照。
22	//	之后       把乙的当前定义改为：月费 4000、额度 1、超额单价 500、税率 20%。
23	//	1 月用量 12、2 月用量 25，均在当时接收，两月均未出账。
24	//	2026-02-15 登记按月取消，2026-03-01 00:00 终止；3 月整月无订阅。
25	//	2026-04-01 按修改后的乙重新开通；4 月无用量。
26	//	2026-05-01 先出 4 月账单，再尝试 3 月，最后补开 2 月、1 月账单。
27	func TestHistoricalBillsKeepLockedTermsAcrossChangeCancelResubscribe(t *testing.T) {
28		s, clk := newTestService(utc(2026, 1, 1, 0, 0))
29	
30		jia := Plan{ID: "jia", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 1000}
31		yiOld := Plan{ID: "yi", MonthlyFee: 2000, IncludedUnits: 20, OveragePrice: 200, TaxRateBasisPoints: 1000}
32		yiNew := Plan{ID: "yi", MonthlyFee: 4000, IncludedUnits: 1, OveragePrice: 500, TaxRateBasisPoints: 2000}
33		jiaTerms := termsOf(jia)
34		yiOldTerms := termsOf(yiOld)
35		yiNewTerms := termsOf(yiNew)
36	
37		mustPlan(t, s, jia)
38		mustPlan(t, s, yiOld)
39		mustAccount(t, s, "u")
40		mustSubscribe(t, s, "u", "jia", utc(2026, 1, 1, 0, 0))
41	
42		// 1 月中旬安排 2 月起改用乙：安排成功时锁定乙的完整条件与生效账期。
43		clk.t = utc(2026, 1, 15, 12, 0)
44		change := mustSchedule(t, s, "u", "yi")
45		if !change.Created || change.Change.TargetPlanID != "yi" ||
46			change.Change.EffectivePeriod != feb(2026) || change.Change.Terms != yiOldTerms {
47			t.Fatalf("scheduled change = %+v, want locked old yi terms effective Feb", change)
48		}
49	
50		// 安排成功后修改乙的当前定义：待生效安排仍持锁，不重新取价。
51		if err := s.UpdatePlan(yiNew); err != nil {
52			t.Fatalf("update yi: %v", err)
53		}
54		st, _ := s.Status("u")
55		if st.PendingChange == nil || st.PendingChange.Terms != yiOldTerms {
56			t.Fatalf("pending change re-priced by plan update: %+v", st.PendingChange)
57		}
58		// 同一目标套餐的重复安排返回原安排、不重新取价。
59		replay, err := s.SchedulePlanChange("u", "yi")
60		if err != nil || replay.Created || replay.Change.Terms != yiOldTerms {
61			t.Fatalf("repeat schedule re-priced: %+v %v", replay, err)
62		}
63	
64		// 1 月接收 12 单位。
65		clk.t = utc(2026, 1, 20, 12, 0)
66		if r, err := s.RecordEvent(Event{AccountID: "u", EventID: "usage-jan", At: utc(2026, 1, 20, 0, 0), Quantity: 12}); err != nil ||
67			!r.Accepted || r.Period != jan(2026) {
68			t.Fatalf("jan usage: %+v %v", r, err)
69		}
70	
71		// 2/1 零点切换自动生效，无需任何操作；当前条件是锁定的旧乙，而非新定义。
72		clk.t = utc(2026, 2, 10, 12, 0)
73		st, _ = s.Status("u")
74		if !st.Subscribed || st.CurrentTerms != yiOldTerms || st.PendingChange != nil {
75			t.Fatalf("feb current terms = %+v pending = %+v, want locked old yi", st.CurrentTerms, st.PendingChange)
76		}
77		// 2 月接收 25 单位。
78		if r, err := s.RecordEvent(Event{AccountID: "u", EventID: "usage-feb", At: utc(2026, 2, 10, 0, 0), Quantity: 25}); err != nil ||
79			!r.Accepted || r.Period != feb(2026) {
80			t.Fatalf("feb usage: %+v %v", r, err)
81		}
82	
83		// 2 月中旬登记按月取消：终止时刻为 3/1 零点，2 月仍按完整月费与额度计费。
84		clk.t = utc(2026, 2, 15, 12, 0)
85		cancelRes := mustCancel(t, s, "u")
86		if !cancelRes.Cancelled || !cancelRes.Cancellation.EndAt.Equal(utc(2026, 3, 1, 0, 0)) {
87			t.Fatalf("cancel result = %+v, want end 2026-03-01", cancelRes)
88		}
89	
90		// 3/1 终止：无有效订阅、无当前套餐；3 月整月空档，事件被拒。
91		clk.t = utc(2026, 3, 10, 12, 0)
92		st, _ = s.Status("u")
93		if st.Subscribed || st.CurrentTerms != (PlanTerms{}) || st.ScheduledEnd != nil {
94			t.Fatalf("status during gap: %+v", st)
95		}
96		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "usage-mar", At: utc(2026, 3, 5, 0, 0), Quantity: 1}); !errors.Is(err, ErrEventBeforeSubscription) {
97			t.Fatalf("march event in gap: %v", err)
98		}
99	
100		// 4/1 按修改后的乙重新开通：当前条件采用新定义；历史用量继续保留。
101		clk.t = utc(2026, 4, 1, 0, 0)
102		mustSubscribe(t, s, "u", "yi", utc(2026, 4, 1, 0, 0))
103		st, _ = s.Status("u")
104		if !st.Subscribed || st.CurrentTerms != yiNewTerms {
105			t.Fatalf("current terms after resubscribe = %+v, want updated yi", st.CurrentTerms)
106		}
107		if u, _ := s.MonthlyUsage("u", jan(2026)); u.Total != 12 {
108			t.Fatalf("jan usage after resubscribe = %d, want 12", u.Total)
109		}
110		if u, _ := s.MonthlyUsage("u", feb(2026)); u.Total != 25 {
111			t.Fatalf("feb usage after resubscribe = %d, want 25", u.Total)
112		}
113	
114		// 5 月：先为重新开通后的 4 月出账——零用量，按新乙：
115		// 月费 4000、税 20% = 800、应付 4800。
116		clk.t = utc(2026, 5, 1, 0, 0)
117		aprBill, err := s.CreateBill("u", apr(2026))
118		if err != nil {
119			t.Fatalf("create apr bill: %v", err)
120		}
121		wantHistoricalBill(t, aprBill, apr(2026), yiNewTerms,
122			0, // total usage
123			4000, 0, 800, 4800)
124	
125		// 重新开通不能把无订阅的 3 月变成可出账月份：出账仍返回账期未被订阅
126		// 覆盖的现有错误，且查询不到该月账单。
127		if _, err := s.CreateBill("u", mar(2026)); !errors.Is(err, ErrBillBeforeSubscription) {
128			t.Fatalf("create march gap bill: %v", err)
129		}
130		if _, err := s.GetBill("u", mar(2026)); !errors.Is(err, ErrBillNotFound) {
131			t.Fatalf("march bill queryable after failed create: %v", err)
132		}
133	
134		// 补开 2 月账单：必须保持安排换套餐时锁定的旧乙条件，
135		// 月费 2000、额度 20、超额 (25-20)*200 = 1000、税 3000*10% = 300、应付 3300。
136		febBill, err := s.CreateBill("u", feb(2026))
137		if err != nil {
138			t.Fatalf("backfill feb bill: %v", err)
139		}
140		wantHistoricalBill(t, febBill, feb(2026), yiOldTerms,
141			25, // total usage
142			2000, 1000, 300, 3300)
143	
144		// 再补开 1 月账单：仍按甲条件，
145		// 月费 1000、额度 10、超额 (12-10)*100 = 200、税 1200*10% = 120、应付 1320。
146		janBill, err := s.CreateBill("u", jan(2026))
147		if err != nil {
148			t.Fatalf("backfill jan bill: %v", err)
149		}
150		wantHistoricalBill(t, janBill, jan(2026), jiaTerms,
151			12, // total usage
152			1000, 200, 120, 1320)
153	
154		// 已成功生成的历史账单，随后查询得到完全相同的计费条件、金额与用量；
155		// 重复出账返回同一张账单。
156		for _, original := range []Bill{aprBill, febBill, janBill} {
157			got, err := s.GetBill("u", original.Period)
158			if err != nil {
159				t.Fatalf("get bill %s: %v", original.Period, err)
160			}
161			if got != original {
162				t.Fatalf("bill %s changed between create and get:\ncreate=%+v\nget   =%+v", original.Period, original, got)
163			}
164			again, err := s.CreateBill("u", original.Period)
165			if err != nil {
166				t.Fatalf("recreate bill %s: %v", original.Period, err)
167			}
168			if again != original {
169				t.Fatalf("bill %s not idempotent:\nfirst =%+v\nagain=%+v", original.Period, original, again)
170			}
171		}
172	
173		// 各月用量查询与账单展示的用量明细分别对应历史月份。
174		for _, w := range []struct {
175			period         Month
176			total, overage int64
177			included       int64
178		}{
179			{jan(2026), 12, 2, 10},
180			{feb(2026), 25, 5, 20},
181			{apr(2026), 0, 0, 1},
182		} {
183			if u, _ := s.MonthlyUsage("u", w.period); u.Total != w.total {
184				t.Fatalf("usage %s = %d, want %d", w.period, u.Total, w.total)
185			}
186			b, _ := s.GetBill("u", w.period)
187			if b.TotalUsage != w.total || b.OverageUnits != w.overage || b.IncludedUnits != w.included {
188				t.Fatalf("bill %s usage detail = total %d over %d included %d, want total %d over %d included %d",
189					w.period, b.TotalUsage, b.OverageUnits, b.IncludedUnits, w.total, w.overage, w.included)
190			}
191		}
192		// 空档 3 月用量查询为零且没有账单。
193		if u, _ := s.MonthlyUsage("u", mar(2026)); u.Total != 0 {
194			t.Fatalf("march usage = %d, want 0", u.Total)
195		}
196	
197		// 补开旧账单后，账户当前套餐仍是重新开通时采用的新乙条件；
198		// 账单按账期排列且只包含 1、2、4 月（3 月空档不在其中）。
199		st, _ = s.Status("u")
200		if !st.Subscribed || st.CurrentTerms != yiNewTerms {
201			t.Fatalf("current terms after backfill = %+v, want updated yi", st.CurrentTerms)
202		}
203		wantSummaries := []struct {
204			period Month
205			due    int64
206		}{
207			{jan(2026), 1320},
208			{feb(2026), 3300},
209			{apr(2026), 4800},
210		}
211		if len(st.Bills) != len(wantSummaries) {
212			t.Fatalf("status bills = %+v, want %d", st.Bills, len(wantSummaries))
213		}
214		for i, w := range wantSummaries {
215			got := st.Bills[i]
216			if got.Period != w.period || got.TotalDue != w.due || got.Paid != 0 ||
217				got.Balance != w.due || got.Settled {
218				t.Fatalf("status bills[%d] = %+v, want period %s due %d unpaid", i, got, w.period, w.due)
219			}
220			if !got.DueAt.Equal(w.period.End().AddDate(0, 0, 7)) {
221				t.Fatalf("status bills[%d] due at = %v", i, got.DueAt)
222			}
223		}
224	}
225	
226	// wantHistoricalBill 断言一张历史账单展示的套餐条件、包含额度、用量明细与
227	// 全部金额字段；尚未登记付款时已付为零、余额等于应付、未付清。
228	func wantHistoricalBill(t *testing.T, b Bill, period Month, wantTerms PlanTerms,
229		totalUsage, monthlyFee, overageFee, tax, totalDue int64) {
230		t.Helper()
231		if b.AccountID != "u" || b.Period != period {
232			t.Fatalf("bill identity = %s/%s, want u/%s", b.AccountID, b.Period, period)
233		}
234		// 套餐条件必须是该账期当时锁定的完整快照，而不只是总额碰巧正确。
235		if b.Terms != wantTerms {
236			t.Fatalf("bill %s terms = %+v, want %+v", period, b.Terms, wantTerms)
237		}
238		wantOverage := totalUsage - wantTerms.IncludedUnits
239		if wantOverage < 0 {
240			wantOverage = 0
241		}
242		if b.TotalUsage != totalUsage || b.IncludedUnits != wantTerms.IncludedUnits || b.OverageUnits != wantOverage {
243			t.Fatalf("bill %s usage detail = total %d included %d overage %d, want total %d included %d overage %d",
244				period, b.TotalUsage, b.IncludedUnits, b.OverageUnits,
245				totalUsage, wantTerms.IncludedUnits, wantOverage)
246		}
247		if b.MonthlyFee != monthlyFee || b.OverageFee != overageFee || b.Tax != tax || b.TotalDue != totalDue {
248			t.Fatalf("bill %s amounts = fee %d overageFee %d tax %d due %d, want %d %d %d %d",
249				period, b.MonthlyFee, b.OverageFee, b.Tax, b.TotalDue,
250				monthlyFee, overageFee, tax, totalDue)
251		}
252		// 尚未登记付款：已付为零、余额等于应付。
253		if b.Paid != 0 || b.Balance != totalDue || b.Settled {
254			t.Fatalf("bill %s payment state = paid %d balance %d settled %v, want 0/%d/false",
255				period, b.Paid, b.Balance, b.Settled, totalDue)
256		}
257		if !b.DueAt.Equal(period.End().AddDate(0, 0, 7)) {
258			t.Fatalf("bill %s due at = %v, want %s+7d", period, b.DueAt, period.End())
259		}
260	}
